#include "ui_workspace.hpp"
#include "ui_extra.hpp"
#include "feature_advanced.hpp"
#include <fstream>
#include <iostream>
#include <cmath>
using namespace scratcher;
static void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
int main(){try{
 auto directory=executableDir()/"ui-workspace-test-data";std::filesystem::create_directories(directory);
 WorkspaceLayout original;original.load(directory/"workspace.json");original.navigator=399;original.inspector=311;original.previewFraction=.47f;original.showInspector=false;original.splitPreview=true;original.preview="Disassembly";original.save();WorkspaceLayout restored;restored.load(directory/"workspace.json");check(restored.navigator==399&&restored.inspector==311,"Pane widths failed to persist");check(std::abs(restored.previewFraction-.47f)<.001f&&restored.splitPreview&&!restored.showInspector&&restored.preview=="Disassembly","Workspace options failed to persist");
 {std::ofstream out(directory/"workspace.json");out<<R"({"navigator":-42,"inspector":9999,"preview_fraction":99,"preview":"invalid"})";}WorkspaceLayout bounded;bounded.load(directory/"workspace.json");check(bounded.navigator==180&&bounded.inspector==600&&bounded.previewFraction==.7f&&bounded.preview=="Pseudocode","Invalid workspace settings were not constrained");
 WorkbenchView form;for(const auto& definition:advancedTools()){form.choose(definition,0x140001000);check(form.operation==definition["name"].get<std::string>(),"Workbench selected the wrong operation");auto schema=definition["inputSchema"];for(auto it=schema["properties"].begin();it!=schema["properties"].end();++it){check(form.fields.contains(it.key()),"Workbench omitted a schema field");if(it->value("type",std::string())=="integer")check(Json::parse(form.fields[it.key()].input.data()).is_number_integer(),"Integer enum/default was not rendered as a number");}}
 Json graph={{"entry","0x1000"},{"nodes",Json::array()},{"edges",Json::array()},{"instruction_count",400}};for(size_t i=0;i<400;++i){auto id=hex(0x1000+i*16);graph["nodes"].push_back({{"id",id},{"instructions",Json::array({{{"mnemonic","RET"},{"operands",""}}})},{"exit","return"}});if(i)graph["edges"].push_back({{"source",hex(0x1000+(i-1)*16)},{"target",id},{"external",false}});}
 ExtraViews views;views.graphScope="D:/fixture.exe";views.loadGraphViews(directory/"graphs.json");views.update("get_control_flow",graph,Json());views.buildGraphLayout();check(views.graphPositions.size()==400,"Graph layout still caps block count");check(views.graphPositions.at(hex(0x1000+399*16)).x>100000,"Deep graph levels collapsed");views.pan={-149,215};views.zoom=.55f;views.saveGraphViews();ExtraViews again;again.graphScope="D:/fixture.exe";again.loadGraphViews(directory/"graphs.json");again.update("get_control_flow",graph,Json());check(again.pan.x==-149&&again.pan.y==215&&std::abs(again.zoom-.55f)<.001f,"Graph view failed to persist");again.graphScope="D:/other.exe";again.update("get_control_flow",graph,Json());check(again.pan.x==20&&again.zoom==1,"Graph view leaked across binaries");
 // Draw the new compute panel without a window, GPU renderer or desktop automation.
 ImGui::CreateContext();auto& io=ImGui::GetIO();io.IniFilename=nullptr;io.DisplaySize={1000,700};io.DeltaTime=1.0f/60;
 unsigned char* pixels=nullptr;int width=0,height=0;io.Fonts->GetTexDataAsRGBA32(&pixels,&width,&height);check(pixels&&width>0&&height>0,"Headless UI font atlas");
 ExtraViews compute;compute.accelerationInfo={{"gpu",{{"available",true},{"name","Test device"},{"free_bytes",1ULL<<30},{"total_bytes",2ULL<<30}}}};compute.similarityIndex={{"index_size",2},{"candidate_functions",3},{"truncated",true},{"elapsed_ms",1.2}};
 compute.similarityResults={{"backend_requested","auto"},{"backend_used","cuda"},{"fallback_reason",""},{"timings",{{"end_to_end_ms",12.0},{"setup_ms",10.0},{"cpu_ms",1.0},{"kernel_ms",0.1}}},{"auto_cpu_baseline_ms",1.0},{"auto_cuda_warm_baseline_ms",0.2},{"auto_minimum_gain_percent",10},{"device_bytes",1024},{"cache_hit",true},{"queries",Json::array({{{"matches",Json::array({{{"address","0x1000"},{"name","function"},{"distance",2},{"similarity_percent",99.2}}})}}})}};
 for(int frame=0;frame<2;++frame){if(frame){compute.accelerationInfo["gpu"]={{"available",false},{"reason","CUDA disabled"}};compute.similarityResults["backend_used"]="cpu";compute.similarityResults["fallback_reason"]="CPU fallback";}ImGui::NewFrame();ImGui::SetNextWindowSize({900,600});ImGui::Begin("Compute panel test");compute.drawAcceleration(0x1000,frame==1);ImGui::End();ImGui::Render();check(ImGui::GetDrawData()&&ImGui::GetDrawData()->CmdListsCount>0,"Acceleration panel emits draw commands for CUDA and CPU fallback states");}ImGui::DestroyContext();
 std::cout<<"Workspace persistence, schema forms, 400-block graph, per-binary graph views and headless acceleration panel checks passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
